Algorithm Paraguas
  Define llueve As Boolean <- True;
  If llueve Then
    Write "Llevo el paraguas";
  EndIf
  Write "Salgo de casa";
EndAlgorithm

Algorithm Montana
  Define estatura As Integer <- 128;
  If estatura >= 120 Then
    Write "Puedes subir a la montaña rusa";
  Else
    Write "Todavía no: vuelve el año que viene";
  EndIf
EndAlgorithm

Algorithm Semaforo
  Define nota As Integer <- 7;
  If nota >= 9 Then
    Write "Excelente";
  Else
    If nota >= 6 Then
      Write "Aprobado";
    Else
      Write "A repasar";
    EndIf
  EndIf
EndAlgorithm

Algorithm Corto
  Define divisor As Integer <- 0;
  If divisor <> 0 And 10 / divisor > 1 Then
    Write "Grande";
  Else
    Write "No se puede dividir";
  EndIf
EndAlgorithm

Algorithm ErrorNumero
  Define edad As Integer <- 12;
  If edad Then
    Write "Hola";
  EndIf
EndAlgorithm

Algorithm ErrorEntonces
  Define edad As Integer <- 12;
  If edad > 10
    Write "Hola";
  EndIf
EndAlgorithm

Algorithm ErrorCierre
  Define edad As Integer <- 12;
  If edad > 10 Then
    Write "Hola";
EndAlgorithm
